B.awB=s(["\u624b\u6a5f\u7248\u6708\u66c6\u79fb\u5230\u7d9c\u5408\u8cc7\u8a0a\u7ad9\u6700\u524d\u65b9\uff0c\u65e5\u671f\u683c\u653e\u5927\u4e26\u6fc3\u7e2e\u591a\u7a2e\u985e\u578b\u6a19\u8a18\u3002","\u9ede\u9078\u65e5\u671f\u6703\u7531\u4e0b\u65b9\u5c55\u958b\u53ef\u62d6\u52d5\u7684\u7576\u65e5\u6642\u9593\u8ef8\uff0c\u6709\u6642\u9593\u7684\u884c\u7a0b\u6703\u4f9d\u958b\u59cb\u6642\u9593\u6392\u5e8f\u3002","\u624b\u6a5f\u4e3b\u6708\u66c6\u4e0d\u518d\u6514\u622a\u65e5\u671f\u5340\u9593\u62d6\u66f3\uff0c\u907f\u514d\u8207\u9801\u9762\u6372\u52d5\u53ca\u5de6\u53f3\u5207\u9801\u624b\u52e2\u885d\u7a81\u3002","\u96fb\u8166\u7248\u7dad\u6301\u539f\u672c\u7684\u5206\u6b04\u8cc7\u8a0a\u8207\u6ed1\u9f20\u62d6\u66f3\u5340\u9593\u529f\u80fd\u3002"],t.s)
B.axi=s(["The mobile calendar now leads the dashboard with larger day cells and compact record markers.","Tapping a date opens a draggable daily timeline with timed events sorted by start time.","The mobile month grid no longer captures range drags, avoiding conflicts with scrolling and page navigation.","Desktop split panels and mouse range selection remain unchanged."],t.s)
B.Xs=new A.cq("v1.2.126+134","\u624b\u6a5f\u6708\u66c6\u5168\u5e45\u700f\u89bd\u8207\u7576\u65e5\u6642\u9593\u8ef8","Expanded mobile calendar and daily timeline",B.awB,B.axi)
B.amL=s(["\u8a18\u5e33\u3001\u884c\u7a0b\u3001\u5de5\u4f5c\u65e5\u8a8c\u8207\u5de5\u4f5c\u4efb\u52d9\u7684\u9010\u9805\u8f38\u5165\u5df2\u5171\u7528\u65b0\u7684\u8a9e\u97f3\u89e3\u6790\u5c64\u3002","\u8a18\u5e33\u53ef\u8fa8\u8b58\u4e2d\u6587\u91d1\u984d\u3001\u591a\u5e63\u5225\u3001\u6536\u652f\u985e\u578b\u3001\u4ed8\u6b3e\u65b9\u5f0f\u8207\u5c0d\u61c9\u9810\u4ed8\u652f\u51fa\u3002","\u884c\u7a0b\u53ef\u8fa8\u8b58\u76f8\u5c0d\u65e5\u671f\u3001\u4e2d\u6587\u6642\u9593\u3001\u63d0\u9192\u3001\u5730\u9ede\u3001\u53c3\u8207\u4eba\u3001\u5de5\u4f5c\u985e\u578b\u8207\u9023\u52d5\u4efb\u52d9\u3002","\u5de5\u4f5c\u65e5\u8a8c\u8207\u4efb\u52d9\u5df2\u88dc\u9f4a\u5de5\u6642\u3001\u963b\u7919\u3001\u4e0b\u4e00\u6b65\u3001\u72c0\u614b\u3001\u9032\u5ea6\u3001\u8ca0\u8cac\u4eba\u8207\u8d77\u8a16\u65e5\u671f\u8fa8\u8b58\u3002","\u9031\u671f\u8a2d\u5b9a\u652f\u63f4\u6bcf\u65e5\u3001\u9593\u9694\u5929\u6578\u3001\u6bcf\u9031\u8907\u9078\u661f\u671f\u3001\u6bcf\u6708\u65e5\u671f\u3001\u6bcf\u6708\u7b2c\u5e7e\u9031\u8207\u622a\u6b62\u65e5\u671f\u3002","\u9010\u9805\u8a9e\u97f3\u6703\u5148\u5957\u7528 Supabase \u89e3\u6790\u8a5e\u5f59\u6b63\u898f\u5316\uff0c\u518d\u4f9d\u7576\u524d\u6b04\u4f4d\u89e3\u6790\u3002"],t.s)
B.aq1=s(["Ledger, schedule, work-log, and task guided entry now share one field-aware speech parser.","Ledger speech recognizes Chinese amounts, currencies, entry types, payment methods, and linked prepaid expenses.","Schedule speech recognizes relative dates, spoken times, reminders, places, participants, work types, and linked tasks.","Work logs and tasks now recognize hours, blockers, next steps, status, progress, owners, and date ranges.","Recurring speech supports daily, interval, weekly multi-day, monthly day, monthly week-position, and end-date settings.","Guided speech applies the latest Supabase parser normalization before interpreting the current field."],t.s)
B.Xv=new A.cq("v1.2.125+133","\u56db\u5927\u7d00\u9304\u9010\u9805\u8a9e\u97f3\u8fa8\u8b58\u5f37\u5316","Guided voice recognition for all four record types",B.amL,B.aq1)
B.ag2=s(["\u652f\u63f4\u532f\u5165\u8207\u9810\u89bd Google Calendar \u7b49\u884c\u4e8b\u66c6\u7522\u751f\u7684 ICS \u6a94\u6848\u3002","\u5c0f\u55b5\u624b\u65b0\u589e\u6587\u5b57\u6b63\u898f\u5316\u3001\u591a\u9805\u7d00\u9304\u5207\u5206\u8207\u610f\u5716\u8a55\u5206\u5206\u985e\u3002","\u624b\u52d5\u8207\u9010\u984c\u8a9e\u97f3\u8f38\u5165\u6574\u5408\u70ba\u540c\u4e00\u6d41\u7a0b\uff0c\u4e26\u53ef\u96a8\u6642\u5207\u63db\u6a21\u5f0f\u3002","\u5efa\u7acb\u7d00\u9304\u6642\u6703\u66ab\u505c\u6d6a\u55b5\u51fa\u73fe\u5169\u5206\u9418\uff0c\u907f\u514d\u5e72\u64fe\u8f38\u5165\u3002"],t.s)
B.aoS=s(["Import and preview ICS files from Google Calendar and other calendar apps.","The assistant adds text normalization, multi-record segmentation, and scored intent classification.","Typed and guided voice entry now share one flow with an always-available mode switch.","Starting an assistant workflow pauses stray-cat appearances for two minutes."],t.s)
B.XZ=new A.cq("v1.2.124+132","\u5c0f\u55b5\u624b\u81ea\u7136\u8a9e\u53e5\u5206\u985e\u8207 ICS \u884c\u7a0b\u532f\u5165",u.Y,B.ag2,B.aoS)
B.ar0=s(["\u53ef\u5f9e\u5e33\u865f\u9078\u55ae\u9078\u64c7 ICS \u6a94\u6848\uff0c\u9810\u89bd\u5f8c\u532f\u5165 Google \u65e5\u66c6\u7b49\u901a\u7528\u884c\u7a0b\uff1b\u652f\u63f4\u5168\u5929\u3001\u63d0\u9192\u3001\u53c3\u8207\u4eba\u53ca\u5e38\u898b\u9031\u671f\u898f\u5247\uff0c\u4e26\u7565\u904e\u65e2\u6709\u91cd\u8907\u884c\u7a0b\u3002","\u5c0f\u55b5\u624b\u65b0\u589e\u6587\u5b57\u6b63\u898f\u5316\u3001\u4e8b\u4ef6\u5207\u5272\u8207\u610f\u5716\u8a55\u5206\u7ba1\u7dda\uff0c\u4e00\u53e5\u8a71\u53ef\u62c6\u6210\u591a\u7b46\u8a18\u5e33\u3001\u884c\u7a0b\u3001\u5de5\u4f5c\u65e5\u8a8c\u6216\u4efb\u52d9\uff0c\u78ba\u8a8d\u9810\u89bd\u5f8c\u624d\u6703\u5beb\u5165\u8cc7\u6599\u3002","\u624b\u52d5\u65b0\u589e\u8207\u8a9e\u97f3\u9010\u984c\u5df2\u5408\u4f75\u70ba\u540c\u4e00\u6d41\u7a0b\uff0c\u53ef\u5728\u6700\u4e0a\u65b9\u96a8\u6642\u5207\u63db\uff1b\u8a9e\u97f3\u6a21\u5f0f\u6703\u9010\u984c\u81ea\u52d5\u8046\u807d\uff0c\u4e5f\u80fd\u4e2d\u9014\u6539\u56de\u9375\u76e4\u8f38\u5165\u3002","\u5df2\u5efa\u7acb iPhone \u8207 iPad \u539f\u751f\u5e73\u53f0\uff0c\u88dc\u9f4a\u8a9e\u97f3\u8fa8\u8b58\u3001\u9ea5\u514b\u98a8\u3001QR \u76f8\u6a5f\u3001ICS \u532f\u5165\u8207\u5e74\u5ea6\u5c01\u5b58\u6240\u9700\u8a2d\u5b9a\uff0c\u4e26\u5957\u7528\u6b63\u5f0f worCat \u5716\u793a\u53ca\u555f\u52d5\u756b\u9762\u3002","\u9ede\u958b\u5c0f\u55b5\u624b\u958b\u59cb\u64cd\u4f5c\u5f8c\uff0c\u6d6a\u55b5\u6703\u66ab\u505c\u51fa\u73fe\u5169\u5206\u9418\uff0c\u907f\u514d\u5efa\u69cb\u7d00\u9304\u6642\u53d7\u5230\u52d5\u756b\u5e72\u64fe\u3002"],t.s)
B.ax2=s(["Import and preview ICS files from Google Calendar and other calendar apps, including all-day events, reminders, attendees, common recurrence rules, and duplicate filtering.","The assistant now uses normalization, event segmentation, and scored intent classification so one request can preview multiple ledger, schedule, work-log, or task records before saving.","Typed and guided voice entry now share one step-by-step flow with an always-available mode switch and automatic listening for each voice question.","The iPhone and iPad platform is now initialized with speech, microphone, QR camera, ICS import, annual archive, App Store icon, and launch-screen support.","Starting an assistant workflow pauses stray-cat appearances for two minutes to keep record creation distraction-free."],t.s)
B.Xz=new A.cq("_hidden_corrupt_v124","PWA \u5c0f\u55b5\u624b\u667a\u6167\u5206\u985e\u8207 ICS \u884c\u7a0b\u532f\u5165",u.Y,B.ar0,B.ax2)
B.ax6=s(["\u5c0f\u55b5\u624b\u8207\u9010\u984c\u8a9e\u97f3\u8f38\u5165\u5df2\u63a5\u4e0a Android \u539f\u751f\u8a9e\u97f3\u8fa8\u8b58\uff0cAPK \u6703\u6b63\u5e38\u8acb\u6c42\u9ea5\u514b\u98a8\u6b0a\u9650\u4e26\u5beb\u5165\u8fa8\u8b58\u6587\u5b57\u3002","\u5e74\u5ea6\u5c01\u5b58\u5df2\u80fd\u5132\u5b58\u5728 Android \u61c9\u7528\u7a0b\u5f0f\u6587\u4ef6\u5340\uff0cJSON \u532f\u51fa\u4e5f\u6703\u547c\u53eb\u7cfb\u7d71\u53e6\u5b58\u6a94\u6848\u4ecb\u9762\u3002","\u9031\u671f\u9805\u76ee\u65b0\u589e\u300c\u6bcf\u9031\u6307\u5b9a\u661f\u671f\u300d\u8207\u300c\u6bcf\u6708\u7b2c\u5e7e\u9031\u7684\u661f\u671f\u300d\uff0c\u661f\u671f\u8207\u7576\u6708\u9031\u6b21\u90fd\u53ef\u8907\u9078\uff0c\u624b\u52d5\u53ca\u8a9e\u97f3\u9010\u984c\u8f38\u5165\u5747\u53ef\u4f7f\u7528\u3002","\u65b0\u589e Supabase \u6b63\u5f0f migration\uff0c\u78ba\u4fdd\u7dda\u4e0a\u9031\u671f\u8cc7\u6599\u80fd\u4fdd\u5b58\u3001\u751f\u6210\uff0c\u4e26\u4fdd\u6301\u9023\u52d5\u884c\u7a0b\u8207\u4efb\u52d9\u7684\u5b8c\u6574\u6027\u3002"],t.s)
B.axR=s(["Assistant and guided speech input now use native Android speech recognition, including microphone permission handling in APK builds.","Annual archives now persist in Android app documents, and JSON export opens the native save-file interface.","Recurring items now support multiple weekdays every week and multiple week positions plus weekdays each month in both manual and guided voice entry.","A formal Supabase migration stores and materializes the new patterns while preserving linked schedule and task consistency."],t.s)
B.XK=new A.cq("v1.2.122+130","\u5b89\u5353\u8a9e\u97f3\u652f\u63f4\u8207\u591a\u9078\u9031\u671f\u6392\u7a0b","Android speech support and flexible weekday recurrences",B.ax6,B.axR)
B.akZ=s(["\u672c\u6708\u9810\u4ed8\u652f\u51fa\u6539\u70ba\u986f\u793a\u5c1a\u5f85\u652f\u4ed8\u7684\u55ae\u4e00\u76f8\u6e1b\u91d1\u984d\uff0c\u907f\u514d\u5927\u6578\u503c\u63db\u884c\u9020\u6210\u6708\u4efd\u9078\u64c7\u8207\u9801\u9762\u4f4d\u7f6e\u8df3\u52d5\u3002","\u624b\u6a5f\u7248\u53ef\u76f4\u63a5\u9ede\u64ca\u9801\u9996\u5927\u8c93\u5716\u958b\u555f\u5c0d\u8a71\u6ce1\u6ce1\u8aaa\u660e\uff0c\u539f\u672c\u7684\u554f\u865f\u8207\u4e0a\u65b9\u7a7a\u767d\u5df2\u79fb\u9664\u3002","\u56db\u500b\u4e3b\u9801\u7684\u624b\u6a5f\u7d71\u8a08\u5361\u7d71\u4e00\u70ba\u5169\u5217\uff1b\u6a19\u984c\u5177\u53ef\u9ede\u64ca\u5916\u89c0\u4e26\u53ef\u67e5\u770b\u8aaa\u660e\uff0c\u8ca0\u503c\u6539\u4ee5\u7d05\u8272\u986f\u793a\uff0c\u9577\u91d1\u984d\u7dad\u6301\u55ae\u884c\u7e2e\u653e\u3002"],t.s)
B.aAq=s(["The monthly prepaid summary now shows one remaining balance value, preventing large totals from wrapping and shifting nearby controls.","On phones, tapping the large page cat opens its explanation in a speech bubble; the question row and unused space are removed.","Phone metric cards now use two rows with tappable labels, red negative values, and single-line scaling for long amounts."],t.s)
B.XU=new A.cq("v1.2.121+129","\u9810\u4ed8\u652f\u51fa\u7c21\u5316\u8207\u624b\u6a5f\u8cc7\u8a0a\u5361\u4e92\u52d5\u8abf\u6574","Simplified prepaid totals and interactive mobile metrics",B.akZ,B.aAq)
B.au4=s(["\u516d\u7a2e\u6536\u652f\u5716\u8868\u5df2\u53d6\u6d88\u5171\u7528\u5916\u5708\u91cf\u8868\uff0c\u5b58\u9322\u7f50\u3001\u7f50\u982d\u3001\u67f1\u72c0\u5716\u3001\u74b0\u5f62\u5716\u3001\u5929\u5e73\u8207\u5713\u9905\u5716\u5747\u6703\u4f9d\u81ea\u8eab\u7d50\u69cb\u5448\u73fe\u6578\u503c\u8b8a\u5316\u3002","\u5929\u5e73\u6a21\u5f0f\u6703\u4f9d\u6536\u5165\u8207\u652f\u51fa\u5dee\u984d\u50be\u659c\u6a6b\u687f\u8207\u5169\u5074\u79e4\u76e4\uff0c\u4e2d\u592e\u8c93\u54aa\u8207\u5e95\u5ea7\u4fdd\u6301\u7a69\u5b9a\u3002","\u624b\u6a5f Web PWA \u5df2\u88dc\u9f4a viewport \u8207\u555f\u52d5\u756b\u9762\u5c3a\u5bf8\u8a2d\u5b9a\uff0c\u907f\u514d\u9996\u5e40\u5148\u4ee5\u904e\u5c0f\u6bd4\u4f8b\u986f\u793a\u518d\u7a81\u7136\u653e\u5927\u3002"],t.s)
B.arS=s(["The six cash-flow modes no longer share one outer-ring meter; each mode now changes its own savings bank, can, bars, donut, scale, or pie structure.","The balance scale now tilts its beam and two pans from the income-expense difference while the center cat and base remain stable.","Mobile Web PWA viewport and startup-screen sizing now prevent the first frame from appearing too small before expanding."],t.s)
B.Y5=new A.cq("v1.2.120+128","\u6536\u652f\u5716\u8868\u7368\u7acb\u52d5\u614b\u8207\u624b\u6a5f\u555f\u52d5\u756b\u9762\u4fee\u6b63","Independent cash-flow animations and mobile startup sizing",B.au4,B.arS)
B.av7=s(["\u6b63\u5f0f Web \u6210\u54c1\u5df2\u91cd\u65b0\u5e36\u5165 Supabase URL\u3001publishable key \u8207 Web Push \u516c\u9470\uff0c\u6703\u54e1\u767b\u5165\u53ca\u8cc7\u6599\u540c\u6b65\u6062\u5fa9\u6b63\u5e38\u3002","\u65b0\u589e\u5c08\u7528\u767c\u5e03\u5efa\u7f6e\u8173\u672c\uff1b\u82e5\u7f3a\u5c11\u4efb\u4f55\u5fc5\u8981\u516c\u958b\u53c3\u6578\u6216\u6210\u54c1\u4ecd\u6703\u9032\u5165\u793a\u7bc4\u6a21\u5f0f\uff0c\u5efa\u7f6e\u6703\u76f4\u63a5\u5931\u6557\u4e26\u505c\u6b62\u4e0a\u50b3\u3002","\u4fdd\u7559 v1.2.118 \u7684\u516d\u6b3e\u8c93\u54aa\u6536\u652f\u91cf\u8868\u3001\u900f\u660e\u88c1\u5207\u8207\u684c\u9762\u8cc7\u8a0a\u5361\u5c3a\u5bf8\u8abf\u6574\u3002"],t.s)
B.akz=s(["The production Web build again includes the Supabase URL, publishable key, and Web Push public key, restoring member sign-in and data sync.","A dedicated release build script now stops immediately if a required public parameter is missing or the output would enter demo mode.","This release retains the six cat cash-flow charts, transparent recrops, and desktop metric-card sizing from v1.2.118."],t.s)
B.Xu=new A.cq("v1.2.119+127","\u4fee\u5fa9\u6b63\u5f0f\u7ad9\u9023\u7dda\u8207\u63a8\u64ad\u8a2d\u5b9a","Restore production connectivity and push settings",B.av7,B.akz)
B.aj9=s(["\u555f\u52d5\u6d41\u7a0b\u6703\u5148\u78ba\u8a8d\u9060\u7aef\u7248\u672c\u4e26\u7b49\u5f85\u65b0\u7248 Service Worker \u63a5\u7ba1\uff0c\u66f4\u65b0\u5f8c\u7b2c\u4e00\u6b21\u958b\u555f\u5373\u53ef\u8f09\u5165\u6700\u65b0\u5167\u5bb9\u3002","\u516d\u6b3e\u6536\u652f\u5716\u8868\u5df2\u6b63\u5f0f\u6539\u7528\u65b0\u8c93\u54aa\u63d2\u5716\uff0c\u4e26\u4f9d\u6536\u5165\u3001\u652f\u51fa\u8207\u7d50\u9918\u52a0\u5165\u6bd4\u4f8b\u74b0\u3001\u5f37\u5ea6\u8207\u52d5\u614b\u8b8a\u5316\u3002","\u516d\u5f35\u91cf\u8868\u5716\u7247\u5df2\u91cd\u65b0\u88c1\u5207\u4e26\u52a0\u5165\u900f\u660e\u5b89\u5168\u908a\u754c\uff0c\u907f\u514d\u986f\u793a\u76f8\u9130\u5716\u5c64\u7684\u908a\u7de3\u3002","\u684c\u6a5f\u7248\u8a18\u5e33\u3001\u884c\u7a0b\u8207\u5de5\u4f5c\u9801\u7684\u4e0a\u65b9\u8cc7\u8a0a\u5361\u6062\u5fa9\u8f03\u5927\u7684\u8c93\u5716\u5c3a\u5bf8\uff0c\u5169\u5217\u6587\u5b57\u5782\u76f4\u7f6e\u4e2d\uff1b\u624b\u6a5f\u7dad\u6301\u7cbe\u7c21\u6392\u7248\u3002"],t.s)
B.azF=s(["Startup now checks the remote version and waits for the new service worker so the latest content appears on the first launch after an update.","All six cash-flow chart modes now use the new cat illustrations with animated income, expense, and balance indicators.","The six chart images were recropped with transparent safe margins so neighboring artwork cannot leak into view.","Desktop ledger, schedule, and work metric cards restore larger cat artwork and vertically center their two text rows; phone layout stays compact."],t.s)
